import {
  Group, Mesh, PlaneGeometry, BoxGeometry,
  MeshStandardNodeMaterial, MeshBasicNodeMaterial,
  Color, RepeatWrapping, LinearFilter,
  Vector2
} from 'three/webgpu';
import {
  float, vec2, vec3, vec4, mix, step, smoothstep,
  time, uniform, uv, texture, positionWorld,
  cameraPosition, normalize, dot, reflect,
  pow, length, max, abs, sin, cos,
  Fn, If, Loop, Break, vec2Uniform, rand, hash,
  screenUV
} from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new Group();
  const cleanups = [];
  const timelines = [];
  const colors = (config.colors || config.intent?.visualSpec?.colors || {});
  const textContent = (config.textContent || config.intent?.visualSpec?.textContent || []);
  const effects = config.effects || config.intent?.visualSpec?.effects || '';

  // --- Constants ---
  const plateW = 1.9;
  const plateH = 1.2;
  const pitch = 1.5;
  const numPlates = 6;
  const loopHeight = numPlates * pitch;
  const bevelSize = 0.03;
  const accentWidth = 0.03;
  const colX = 0.9;
  const fullScrollRange = loopHeight; // used for fly-through

  // --- Backdrop (avoid FLAT_VOID) ---
  const backGeo = new PlaneGeometry(7, 7);
  const backMat = new MeshBasicNodeMaterial();
  // Vertical gradient + subtle horizontal light stripe on left
  const backFn = Fn(() => {
    const vUv = uv();
    const grain = rand(vUv * 100.0 + float(time).mul(0.1)).mul(0.02).add(0.98);
    const c0 = vec3(0.043, 0.043, 0.063); // #0b0b10
    const c1 = vec3(0.078, 0.078, 0.102); // #14141a
    let col = mix(c0, c1, vUv.y).mul(grain);
    // Add a soft warm light wedge from left side
    const leftWedge = smoothstep(0.6, 0.1, vUv.x).mul(0.06);
    col += vec3(0.25, 0.18, 0.10).mul(leftWedge);
    return vec4(col, 1.0);
  });
  backMat.colorNode = backFn();
  backMat.depthWrite = false;
  const backdrop = new Mesh(backGeo, backMat);
  backdrop.position.z = -2.5;
  group.add(backdrop);

  // --- Load the photographic texture ---
  let photoTexture = null;
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      tex.wrapS = tex.wrapT = RepeatWrapping;
      tex.repeat.set(1 / 2, 1);
      tex.anisotropy = 4;
      // Apply to all plate materials once loaded
      plates.forEach((p, i) => {
        p.plate.material.map = tex;
        // Offset for distinct crop
        const offsetX = (i % 2) * 0.5; // 0, 0.5, 1, 0, 0.5, 1 …
        const offsetY = Math.floor(i / 2) * (1 / 3); // 0, 0, 1/3, 1/3, 2/3, 2/3
        p.plate.material.map.offset.set(offsetX, offsetY);
        p.plate.material.map.center.set(0.5, 0.5);
        p.plate.material.needsUpdate = true;
      });
    }).catch(() => {
      // Fallback: use procedural photograph (warm tones)
      const fallbackFn = Fn(([seed]) => {
        const vUv = uv();
        const g = hash(vUv * 37.0 + seed).mul(0.3).add(0.2);
        const noise = sin(vUv.x * 300.0 * seed + vUv.y * 200.0).mul(0.1);
        const base = 0.3 + g + noise;
        const contrast = mix(0.15, 0.6, smoothstep(0.2, 0.8, base));
        const warm = vec3(0.9, 0.8, 0.7).mul(contrast);
        const vig = smoothstep(0.5, 0.0, length(vUv.sub(0.5)).mul(1.8));
        const final = mix(vec3(0.08, 0.06, 0.05), warm, vig);
        return vec4(final, 1.0);
      });
      plates.forEach((p, i) => {
        p.plate.material.colorNode = fallbackFn(float(i));
        p.plate.material.needsUpdate = true;
      });
    });
  } else {
    // No imageUrl – use procedural fallback to avoid flat void
    const fallbackFn = Fn(([seed]) => {
      const vUv = uv();
      const g = hash(vUv * 37.0 + seed).mul(0.3).add(0.2);
      const noise = sin(vUv.x * 300.0 * seed + vUv.y * 200.0).mul(0.1);
      const base = 0.3 + g + noise;
      const contrast = mix(0.15, 0.6, smoothstep(0.2, 0.8, base));
      const warm = vec3(0.9, 0.8, 0.7).mul(contrast);
      const vig = smoothstep(0.5, 0.0, length(vUv.sub(0.5)).mul(1.8));
      const final = mix(vec3(0.08, 0.06, 0.05), warm, vig);
      return vec4(final, 1.0);
    });
    // assign later
  }

  // --- Headline ---
  const headlineItem = textContent.find(t => t.role === 'headline' || t.text === 'Inside the atelier');
  if (headlineItem) {
    const h = ctx.fontAtlas.createText(headlineItem.text, {
      fontSize: 68,
      color: colors.paper || '#e8ecf2',
      align: 'left'
    });
    h.position.set(-1.6, 1.9, 0.1);
    h.scale.set(0.002, 0.002, 0.002);
    group.add(h);
  }

  // --- Build plates ---
  const plates = [];
  const captionItems = textContent.filter(t => t.role === 'caption' || (t.typography && t.typography.fontSize <= 24));

  for (let i = 0; i < numPlates; i++) {
    const pg = new Group();
    pg.position.set(colX, -i * pitch, 0);

    // Plate surface
    const pGeo = new PlaneGeometry(plateW, plateH);
    const pMat = new MeshStandardNodeMaterial();
    pMat.roughness = 0.6;
    pMat.metalness = 0.1;
    pMat.clearcoat = 0.1;
    pMat.colorNode = vec4(0.3, 0.2, 0.15, 1.0); // temporary warm placeholder
    const plate = new Mesh(pGeo, pMat);
    pg.add(plate);

    // Bevel frame (ink)
    const bGeo = new BoxGeometry(plateW + bevelSize * 2, plateH + bevelSize * 2, 0.03);
    const bMat = new MeshStandardNodeMaterial();
    bMat.color = new Color(colors.ink || '#16161d');
    bMat.roughness = 0.5;
    bMat.metalness = 0.5;
    const bevel = new Mesh(bGeo, bMat);
    bevel.position.z = -0.015;
    pg.add(bevel);

    // Accent strip (left edge, red)
    const aGeo = new PlaneGeometry(accentWidth, plateH);
    const aMat = new MeshBasicNodeMaterial();
    aMat.color = new Color(colors.accent || '#ff2a38');
    const accent = new Mesh(aGeo, aMat);
    accent.position.set(-plateW / 2 - bevelSize, 0, 0.015);
    pg.add(accent);

    group.add(pg);
    plates.push({
      group: pg,
      plate,
      accent,
      caption: null, // will be world-space text for focused plate
      focused: false,
      plateIdx: i,
      accentMat: aMat
    });
  }

  // --- World-space caption (single, positioned at x=-1.6) ---
  const captionText = ctx.fontAtlas.createText('', {
    fontSize: 18,
    color: colors.paper || '#e8ecf2',
    align: 'left',
    letterSpacingPx: 12
  });
  captionText.position.set(-1.6, 0, 0.1);
  captionText.scale.set(0.002, 0.002, 0.002);
  captionText.visible = false;
  group.add(captionText);

  // --- Scroll state ---
  const scrollState = {
    currentY: 0,
    targetY: 0,
    velocity: 0,
    animId: null,
    settling: false
  };

  function updatePlates(y) {
    // Wrap y to [0, loopHeight)
    const wrappedY = ((y % loopHeight) + loopHeight) % loopHeight;
    for (let i = 0; i < numPlates; i++) {
      let py = -i * pitch - wrappedY;
      // Wrap into [-loopHeight/2, loopHeight/2]
      while (py < -loopHeight / 2) py += loopHeight;
      while (py > loopHeight / 2) py -= loopHeight;
      plates[i].group.position.y = py;
    }

    // Find focused plate (nearest to y=0)
    let minDist = Infinity;
    let focusedIdx = -1;
    for (let i = 0; i < numPlates; i++) {
      const py = plates[i].group.position.y;
      const dist = Math.abs(py);
      if (dist < minDist) {
        minDist = dist;
        focusedIdx = i;
      }
    }
    // Update focus state
    for (let i = 0; i < numPlates; i++) {
      const isFocused = i === focusedIdx && minDist < pitch / 2;
      if (isFocused && !plates[i].focused) {
        plates[i].focused = true;
        // Scale up plate
        gsap.to(plates[i].plate.scale, { x: 1.06, y: 1.06, duration: 0.35, ease: 'cubic-bezier(0.215,0.61,0.355,1)' });
        // Accent emissive
        gsap.to(plates[i].accentMat, { emissiveIntensity: 1.4, duration: 0.35, ease: 'cubic-bezier(0.215,0.61,0.355,1)' });
        // Update world caption text and position
        const capIdx = plates[i].plateIdx;
        const capItem = captionItems[capIdx];
        if (capItem) {
          captionText.visible = true;
          captionText.updateText(capItem.text); // assumes method exists, else re-create
          // Position caption vertically near the focused plate
          const plateWorldY = plates[i].group.position.y;
          captionText.position.y = plateWorldY + 0.1;
          // Fade in
          gsap.fromTo(captionText, { opacity: 0 }, { opacity: 1, duration: 0.35, ease: 'power2.out' });
        }
      } else if (!isFocused && plates[i].focused) {
        plates[i].focused = false;
        // Scale down plate
        gsap.to(plates[i].plate.scale, { x: 1.0, y: 1.0, duration: 0.35, ease: 'cubic-bezier(0.215,0.61,0.355,1)' });
        // Accent emissive off
        gsap.to(plates[i].accentMat, { emissiveIntensity: 0, duration: 0.35, ease: 'cubic-bezier(0.215,0.61,0.355,1)' });
        // Only hide caption if unfocusing current caption plate
        if (i === focusedIdx) {
          gsap.to(captionText, { opacity: 0, duration: 0.2, onComplete: () => { captionText.visible = false; } });
        }
      }
    }
  }

  function scrollTick() {
    const dt = 0.016;
    scrollState.velocity *= (1 - 0.12);
    scrollState.currentY += scrollState.velocity * dt;
    updatePlates(scrollState.currentY);

    // Fly-through depth offset
    const depthProg = (scrollState.currentY / fullScrollRange) * 2 - 1;
    group.userData.cameraDepthOffset = depthProg * 2.5 * 0.5;
    ctx.emit('camera-depth-offset', { offset: group.userData.cameraDepthOffset });

    if (Math.abs(scrollState.velocity) > 0.001) {
      scrollState.animId = requestAnimationFrame(scrollTick);
    } else {
      // Weighted settle
      const tl = gsap.to(scrollState, {
        velocity: 0,
        duration: 0.9,
        ease: 'power4.out',
        onUpdate: () => {
          scrollState.currentY += scrollState.velocity * 0.016;
          updatePlates(scrollState.currentY);
        }
      });
      timelines.push(tl);
    }
  }

  group.userData.handlers = {
    scroll: (e) => {
      if (e.deltaY) {
        scrollState.velocity += e.deltaY * 0.01 * 1.5;
        scrollState.velocity = Math.max(-3, Math.min(3, scrollState.velocity));
        if (scrollState.animId) cancelAnimationFrame(scrollState.animId);
        scrollState.animId = requestAnimationFrame(scrollTick);
      }
    }
  };

  // Initial update
  updatePlates(0);

  // --- Lights: key + rim + fill ---
  const key = new ctx.THREE.DirectionalLight(0xffeedd, 1.2); // warm key
  key.position.set(2, 3, 4);
  group.add(key);
  const rim = new ctx.THREE.DirectionalLight(0xff2a38, 0.8); // accent rim
  rim.position.set(-3, 2, -1);
  group.add(rim);
  const fill = new ctx.THREE.AmbientLight(0x222233, 0.6);
  group.add(fill);

  // --- Contact shadow plane ---
  const shadowGeo = new PlaneGeometry(3.5, 0.8);
  const shadowMat = new MeshBasicNodeMaterial({
    transparent: true,
    depthWrite: false
  });
  const shadowFn = Fn(() => {
    const vUv = uv();
    const alpha = smoothstep(0.4, 0.0, length(vUv.sub(0.5).mul(1.0, 0.5))).mul(0.5);
    return vec4(0.0, 0.0, 0.0, alpha);
  });
  shadowMat.colorNode = shadowFn();
  const shadow = new Mesh(shadowGeo, shadowMat);
  shadow.position.set(colX, -3.2, -0.1);
  shadow.rotation.x = -Math.PI / 2;
  group.add(shadow);

  // --- Cinematic primitive: fly-through ---
  for (const prim of (config.cinematicPrimitives || [])) {
    if (prim.name === 'fly-through') {
      const result = ctx.primitives['fly-through'](group, {
        depthUnits: 2.5,
        scrollRange: fullScrollRange,
        scrollState: scrollState
      });
      if (result) {
        cleanups.push(result.cleanup);
        if (result.timeline) timelines.push(result.timeline);
      }
    }
  }

  // --- Cleanup ---
  group.userData.cleanup = () => {
    timelines.forEach(tl => tl.kill());
    if (scrollState.animId) cancelAnimationFrame(scrollState.animId);
    cleanups.forEach(fn => fn());
    backGeo.dispose(); backMat.dispose();
    group.traverse(child => {
      if (child.isMesh) {
        child.geometry && child.geometry.dispose();
        child.material && child.material.dispose();
      }
    });
    // Remove caption text
    captionText.remove();
  };

  return group;
}
